  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Record C07 reports absolute oral bioavailability of labetalol as 29.9 ± 1.7% in normal subjects after 200 mg orally versus 0.5 mg/kg i.v., which is above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Record C41 reports levothyroxine tablet bioavailability of 79.6% versus intravenous LT4 in a crossover study, strongly supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Record C16 reports phenylethylmalonamide oral bioavailability of 91 ± 4.4% versus intravenous dosing in normal volunteers, well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All evidence molecules have high assay-transfer scores, and their strongest condition-matched numeric records consistently support oral bioavailability at or above 20%, so the prediction is high.",
  "evidence_gaps": [
    "A few isolated records report values below 20%, but they are not the strongest condition-matched records and do not establish a molecule-level low direction.",
    "Some records are qualitative or unspecified in bioavailability type, but the strongest absolute measurements consistently support high bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

